$ErrorActionPreference="Stop"
Set-StrictMode -Version 2.0

# Read-only readiness gate after explicitly authorized clean installs/profile creation.
$RepoRoot=Split-Path -Parent $PSScriptRoot;Set-Location $RepoRoot
$Adb="C:\Users\User\AppData\Local\Android\Sdk\platform-tools\adb.exe";$Package="com.vladimir.messenger"
$CleanState=Join-Path $env:TEMP "apu-m8e-clean-install-v111618-state.json";$AnnaReset=Join-Path $env:TEMP "apu-m8e-anna-profile-reset.json"
$ExpectedCleanHash="20FDAC7F65E5774A45005ABF7B272962366D8ABB839FC4C1E4387BD74605F110";$ExpectedAnnaResetHash="C6CBBC563D0A411ADD5540F3279717641937394CD620C1915737CC2F6D7A94CB"
$StatePath=Join-Path $env:TEMP "apu-m8e-phone-readiness-state.json";$LogRoot=Join-Path $env:TEMP "apu-m8e-phone-readiness-logs"
if((Test-Path $StatePath) -or (Test-Path $LogRoot)){throw "Readiness gate already attempted; preserve evidence"}
if((Get-FileHash $CleanState -Algorithm SHA256).Hash -ne $ExpectedCleanHash){throw "Clean-install evidence mismatch"};if((Get-FileHash $AnnaReset -Algorithm SHA256).Hash -ne $ExpectedAnnaResetHash){throw "Anna-reset evidence mismatch"}
$Phones=@([pscustomobject]@{Name="Anna";Serial="AUYF6R5923006121"},[pscustomobject]@{Name="Zhenya";Serial="3B665800EES00000"},[pscustomobject]@{Name="Stas";Serial="11567254BK001192"})
$Lines=@(& $Adb devices);$Visible=@{};foreach($Line in $Lines){if($Line -match "^(\S+)\s+(\S+)$"){$Visible[$Matches[1]]=$Matches[2]}};foreach($Phone in $Phones){if(-not $Visible.ContainsKey($Phone.Serial) -or $Visible[$Phone.Serial] -ne "device"){throw "$($Phone.Name) unavailable"}}
New-Item -ItemType Directory -Path $LogRoot|Out-Null;$Results=@();Write-Host "=== M8-E PHONE READINESS (READ-ONLY) ==="
foreach($Phone in $Phones){$Serial=$Phone.Serial;$PidText=((& $Adb -s $Serial shell pidof $Package)-join " ").Trim();if(-not $PidText -or $PidText -notmatch "^\d+$"){throw "$($Phone.Name) process not running: $PidText"};$Dump=@(& $Adb -s $Serial shell dumpsys package $Package);$Version=(($Dump|Where-Object{$_ -match "^\s*versionName="}|Select-Object -First 1) -as [string]).Trim();$Code=(($Dump|Where-Object{$_ -match "^\s*versionCode="}|Select-Object -First 1) -as [string]).Trim();$Uid=(($Dump|Where-Object{$_ -match "^\s*(userId|appId)="}|Select-Object -First 1) -as [string]).Trim();if($Version -ne "versionName=v11.16.18"){throw "$($Phone.Name) version mismatch: $Version"}
 $Log=@(& $Adb -s $Serial logcat --pid=$PidText -d -t 3000);$LogPath=Join-Path $LogRoot "$($Phone.Name).log";$Log|Set-Content $LogPath -Encoding UTF8;$Text=$Log -join"`n";$Scheduled=$Text -match "M8 bounded relay wake scheduled";$Engine=$Text -match "Engine started\. NodeId:";$Durable=$Text -match "Relay custody mode: durable-encrypted, quarantined: 0";$Fatal=$Text -match "FATAL EXCEPTION|Process: com\.vladimir\.messenger.*AndroidRuntime";$Jobs=@(& $Adb -s $Serial shell dumpsys jobscheduler $Package);$JobText=$Jobs -join"`n";$WorkManagerJob=$JobText -match "androidx\.work\.impl\.background\.systemjob\.SystemJobService|com\.vladimir\.messenger"
 Write-Host "$($Phone.Name): PID=$PidText $Version $Uid schedule=$Scheduled engine=$Engine durable0=$Durable workJob=$WorkManagerJob fatal=$Fatal";if(-not $Scheduled -or -not $Engine -or -not $Durable -or -not $WorkManagerJob -or $Fatal){throw "$($Phone.Name) readiness markers failed; preserve $LogPath"};$Results+=[pscustomobject]@{Name=$Phone.Name;Serial=$Serial;Version=$Version;VersionCode=$Code;Uid=$Uid;ProcessId=$PidText;scheduleMarker=$Scheduled;engineStartedMarker=$Engine;durableEncryptedQuarantineZero=$Durable;workManagerJobVisible=$WorkManagerJob;fatalInCurrentProcess=$Fatal;logPath=$LogPath;logSha256=(Get-FileHash $LogPath -Algorithm SHA256).Hash}}
$State=[ordered]@{schema=1;outcome="PASS";capturedUtc=(Get-Date).ToUniversalTime().ToString("o");phones=$Results;installPerformed=$false;launchPerformed=$false;forceStopUsed=$false;logcatCleared=$false;dataCleared=$false}
$State|ConvertTo-Json -Depth 8|Set-Content $StatePath -Encoding UTF8;$Hash=(Get-FileHash $StatePath -Algorithm SHA256).Hash;Write-Host "`nOutcome: PASS";Write-Host "State: $StatePath";Write-Host "State SHA256: $Hash";Write-Host "Durable encrypted/quarantine0: 3/3";Write-Host "WorkManager scheduled: 3/3";Write-Host "Phone changes: False";Write-Host "M8-E PHONE READINESS PASS"
